const SECURE_API='https://dhhwcqczvcbwdwllfcun.supabase.co/functions/v1/multaqa-secure';
let staffToken=localStorage.getItem('multaqa_staff_session')||'',secureEmployee=null,secureDirectory={employees:[],classes:[],buses:[]},activeGrade=5,currentRoster=null,broadcastStream=null,broadcastRecorder=null,broadcastChunks=[],broadcastVideoFile=null,caseUploadFile=null,teacherPhotoFile=null,teacherProfilesCache=[],supportSelectedStudent=null;
