async function renderBroadcasts(){
 stopBroadcastCamera(true);broadcastVideoFile=null;const d=await staffApi('broadcasts'),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Muscat'}).format(new Date());
 S('staffPane').innerHTML='<div class="today-title"><div><small>التصوير والتوثيق والتقييم</small><h2>📻 الإذاعة المدرسية</h2></div></div><div class="broadcast-layout"><section class="staff-card broadcast-form"><h3>بيانات الإذاعة</h3><label>عنوان الإذاعة</label><input id="broadcastTitle" placeholder="مثال: قيمنا تصنع مستقبلنا"><div class="form-row"><div><label>المعلمة</label><select id="broadcastTeacher">'+broadcastTeacherOptions()+'</select></div><div><label>التاريخ</label><input id="broadcastDate" type="date" value="'+today+'"></div></div><label>الطالبات المشاركات</label><textarea id="broadcastParticipants" placeholder="اكتبي كل اسم في سطر، أو افصلي الأسماء بفاصلة"></textarea><div class="form-row"><div><label>حالة الحدث</label><select id="broadcastStatus"><option value="planned">مخطط لها</option><option value="live">🔴 حدث مباشر الآن</option><option value="completed">مكتملة</option><option value="cancelled">ملغاة</option></select></div><div><label>تقييم الإذاعة</label><select id="broadcastRating"><option value="">بدون تقييم</option><option value="1">⭐</option><option value="2">⭐⭐</option><option value="3">⭐⭐⭐</option><option value="4">⭐⭐⭐⭐</option><option value="5">⭐⭐⭐⭐⭐</option></select></div></div><label>ملاحظات التقييم</label><textarea id="broadcastEvaluation" placeholder="نقاط القوة وما يحتاج تطويرًا"></textarea><button class="staff-primary broadcast-save" onclick="saveBroadcast()">حفظ الإذاعة والفيديو</button><button class="broadcast-live-btn" onclick="startLiveBroadcast()">🔴 بدء الحدث المباشر وحفظه</button><div id="broadcastSaveState"></div></section><section class="staff-card broadcast-camera-card"><h3>📹 كاميرا الإذاعة</h3><video id="broadcastCamera" playsinline muted controls></video><div class="camera-actions"><button onclick="enableBroadcastCamera()">📷 تفعيل الكاميرا</button><button id="broadcastRecordBtn" onclick="startBroadcastRecording()">⏺ تسجيل فيديو</button><button id="broadcastStopBtn" onclick="stopBroadcastRecording()" disabled>⏹ إيقاف التسجيل</button></div><label class="broadcast-file-pick">أو اختيار فيديو من الجهاز<input type="file" accept="video/mp4,video/webm,video/quicktime" capture="environment" onchange="useBroadcastFile(this)"></label><p id="broadcastCameraState">لم يتم اختيار فيديو بعد.</p></section></div><h3 class="staff-section-title">سجل الإذاعات</h3><div class="broadcast-list">'+((d.items||[]).map(broadcastCard).join('')||'<div class="staff-empty">لا توجد إذاعات مسجلة بعد.</div>')+'</div>';
}
function broadcastCard(x){
 const people=(x.participants||[]).join('، ');return '<article class="staff-card broadcast-card"><div class="broadcast-card-head"><div><small>'+esc(x.broadcast_date)+'</small><h3>'+esc(x.title)+'</h3></div><span class="broadcast-status '+esc(x.event_status)+'">'+broadcastStatusLabel(x.event_status)+'</span></div><p><b>المعلمة:</b> '+esc(x.teacher_name||'—')+'</p><p><b>الطالبات:</b> '+esc(people||'لم تُسجّل أسماء')+'</p>'+(x.video_url?'<video controls playsinline src="'+esc(x.video_url)+'"></video>':'<div class="broadcast-no-video">لا يوجد فيديو مرفق</div>')+'<div class="broadcast-rating"><b>التقييم:</b> '+(x.rating?'⭐'.repeat(x.rating):'لم يُقيّم')+(x.evaluation_note?'<p>'+esc(x.evaluation_note)+'</p>':'')+'</div></article>';
}
window.enableBroadcastCamera=async()=>{
 try{stopBroadcastCamera(true);broadcastStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:true});const v=S('broadcastCamera');v.srcObject=broadcastStream;v.removeAttribute('src');v.muted=true;await v.play();S('broadcastCameraState').textContent='✅ الكاميرا والميكروفون جاهزان للتسجيل.'}catch(e){S('broadcastCameraState').textContent='تعذر تشغيل الكاميرا. اسمحي للموقع باستخدام الكاميرا والميكروفون، أو اختاري فيديو من الجهاز.'}
};
function stopBroadcastCamera(discard){if(broadcastRecorder&&broadcastRecorder.state!=='inactive')try{if(discard)broadcastRecorder.onstop=null;broadcastRecorder.stop()}catch{};if(broadcastStream){broadcastStream.getTracks().forEach(t=>t.stop());broadcastStream=null}}
window.startBroadcastRecording=async()=>{
 if(!broadcastStream)await enableBroadcastCamera();if(!broadcastStream||!window.MediaRecorder)return;
 const types=['video/mp4;codecs=h264,aac','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm'],mime=types.find(x=>MediaRecorder.isTypeSupported(x))||'';broadcastChunks=[];
 try{broadcastRecorder=new MediaRecorder(broadcastStream,mime?{mimeType:mime}:undefined)}catch(e){return toast('تعذر بدء التسجيل على هذا الجهاز')}
 broadcastRecorder.ondataavailable=e=>{if(e.data&&e.data.size)broadcastChunks.push(e.data)};
 broadcastRecorder.onstop=()=>{const recordedType=broadcastRecorder.mimeType||mime||'video/webm',type=recordedType.includes('mp4')?'video/mp4':'video/webm',blob=new Blob(broadcastChunks,{type}),ext=type==='video/mp4'?'mp4':'webm';broadcastVideoFile=new File([blob],'school-broadcast-'+Date.now()+'.'+ext,{type});const v=S('broadcastCamera');v.srcObject=null;v.src=URL.createObjectURL(blob);v.muted=false;v.controls=true;S('broadcastCameraState').textContent='✅ اكتمل التسجيل: '+Math.max(1,Math.round(blob.size/1024/1024))+' MB';S('broadcastRecordBtn').disabled=false;S('broadcastStopBtn').disabled=true};
 broadcastRecorder.start(1000);S('broadcastRecordBtn').disabled=true;S('broadcastStopBtn').disabled=false;S('broadcastCameraState').textContent='🔴 التسجيل جارٍ الآن…';
};
window.stopBroadcastRecording=()=>{if(broadcastRecorder&&broadcastRecorder.state!=='inactive')broadcastRecorder.stop()};
window.useBroadcastFile=input=>{const f=input.files&&input.files[0];if(!f)return;if(f.size>250*1024*1024){input.value='';return toast('حجم الفيديو يجب ألا يتجاوز 250 MB')}broadcastVideoFile=f;stopBroadcastCamera(true);const v=S('broadcastCamera');v.srcObject=null;v.src=URL.createObjectURL(f);v.muted=false;v.controls=true;S('broadcastCameraState').textContent='✅ تم اختيار '+f.name+' — '+Math.max(1,Math.round(f.size/1024/1024))+' MB'};
function broadcastPayload(statusOverride){return{title:S('broadcastTitle').value.trim(),teacher_name:S('broadcastTeacher').value,broadcast_date:S('broadcastDate').value,participants:S('broadcastParticipants').value.split(/[،,\n]/).map(x=>x.trim()).filter(Boolean),event_status:statusOverride||S('broadcastStatus').value,rating:+S('broadcastRating').value||null,evaluation_note:S('broadcastEvaluation').value.trim()}}
window.saveBroadcast=async statusOverride=>{
 const payload=broadcastPayload(statusOverride),state=S('broadcastSaveState');if(payload.title.length<2)return toast('اكتبي عنوان الإذاعة أولًا');state.textContent='جاري حفظ الإذاعة…';
 try{const d=await staffApi('save_broadcast',payload);if(broadcastVideoFile){state.textContent='جاري رفع الفيديو…';const mime=broadcastVideoFile.type.includes('mp4')?'video/mp4':broadcastVideoFile.type.includes('quicktime')?'video/quicktime':'video/webm',u=await staffApi('prepare_broadcast_upload',{id:d.item.id,mime_type:mime}),up=await fetch(u.signed_url,{method:'PUT',headers:{'Content-Type':mime,'x-upsert':'false'},body:broadcastVideoFile});if(!up.ok)throw Object.assign(new Error('upload_failed'),{code:'upload_failed'});await staffApi('complete_broadcast_video',{id:d.item.id,path:u.path})}stopBroadcastCamera(true);toast(statusOverride==='live'?'🔴 بدأ الحدث المباشر وتم حفظه':'✅ تم حفظ الإذاعة');await renderBroadcasts()}catch(e){state.textContent=staffError(e);toast(staffError(e))}
};
