window.selectSupportStudent=(id,name,className)=>{supportSelectedStudent={school_id:id,name,class_name:className};S('supportStudentId').value=id;S('supportSearchResults').innerHTML='<div class="selected-support-student"><b>'+esc(name)+'</b><small>'+esc(className)+' • '+esc(id)+'</small></div>'};
window.saveStudentSupport=async()=>{const sid=S('supportStudentId').value;if(!sid)return toast('اختاري الطالبة أولًا');try{await staffApi('classify_student_support',{student_school_id:sid,student:supportSelectedStudent,financial_support:S('supportFinancial').checked,academic_category:S('supportAcademic').value,support_priority:S('supportPriority').value,support_program:S('supportProgram').value,support_note:S('supportNote').value});phCapture('student_support_classified',{financial:S('supportFinancial').checked,academic_category:S('supportAcademic').value});toast('تم حفظ تصنيف الطالبة');renderStudentSupport()}catch(e){toast(staffError(e))}};
function renderSocialWorker(){if(!caseAccess())return S('staffPane').innerHTML='<div class="staff-empty">هذا القسم خاص بالإدارة والأخصائية الاجتماعية.</div>';S('staffPane').innerHTML='<div class="today-title"><div><small>ملفات سرية • خطط • متابعة • مرفقات</small><h2>🤝 قسم الأخصائية الاجتماعية</h2></div></div><div class="case-search"><select id="caseClass"><option value="">كل الصفوف</option>'+secureDirectory.classes.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select><input id="caseQuery" placeholder="اسم الطالبة"><button class="staff-primary" onclick="searchStudentCases()">بحث</button></div><div id="caseResults"></div><div id="caseDetail"></div>'}
