async function renderAnalytics(){
 const now=new Date(),from=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10),to=now.toISOString().slice(0,10),d=await staffApi('analytics',{from,to});const bar=(obj,labels={})=>{const a=Object.entries(obj||{}),max=Math.max(1,...a.map(x=>x[1]));return '<div class="bars">'+a.map(([k,v])=>'<div><span>'+esc(labels[k]||activityNames[k]||k)+'</span><i><b style="width:'+Math.round(v/max*100)+'%"></b></i><strong>'+v+'</strong></div>').join('')+'</div>'};const st={present:'حضور',absent:'غياب',late:'تأخر',excused:'بعذر',permission:'استئذان',partial_permission:'استئذان جزئي',approved:'موافق',pending:'قيد الانتظار',active:'نشط',completed:'مكتمل',organized:'صف منظم',no_teacher:'بلا معلمة',problem:'مشكلة'},rs={health:'صحي',medical_appointment:'موعد طبي',family:'أسري',child:'طفل',government:'جهة حكومية',emergency:'طارئ',official_task:'مهمة رسمية',transport:'مواصلات',other:'أخرى'};S('staffPane').innerHTML='<div class="today-title"><div><small>من '+from+' إلى '+to+'</small><h2>📊 مؤشرات الشهر</h2></div><span class="posthog-chip">PostHog • تحديث دوري</span></div><div class="kpi-grid compact"><div><small>الأنشطة</small><b>'+d.activities.total+'</b></div><div><small>مهام الأنشطة</small><b>'+d.activity_tasks.total+'</b></div><div><small>الموهوبات</small><b>'+d.gifted.total+'</b></div><div><small>متابعات الحالات</small><b>'+d.case_followups.total+'</b></div></div><div class="analytics-grid"><section class="staff-card"><h3>حضور الطالبات</h3>'+bar(d.students.status,st)+'</section><section class="staff-card"><h3>حضور المعلمات</h3>'+bar(d.teachers.status,st)+'</section><section class="staff-card"><h3>أسباب الاستئذان</h3>'+bar(d.permissions.reasons,rs)+'</section><section class="staff-card"><h3>بلاغات الفصول</h3>'+bar(d.observations.status,st)+'</section><section class="staff-card"><h3>الأنشطة حسب النوع</h3>'+bar(d.activities.types)+'</section><section class="staff-card"><h3>حالة مهام الأنشطة</h3>'+bar(d.activity_tasks.status,st)+'</section><section class="staff-card"><h3>مجالات المواهب</h3>'+bar(d.gifted.talents)+'</section><section class="staff-card"><h3>أنواع متابعة الحالات</h3>'+bar(d.case_followups.types)+'</section></div>';phCapture('analytics_viewed',{period:'month'})}
function renderSecurity(){S('staffPane').innerHTML='<div class="two-col"><section class="staff-card"><h2>🔐 إصدار رمز شخصي</h2><p class="staff-help">اختاري الموظفة. يمكن للنظام إنشاء رمز مؤقت، ويُطلب تغييره عند أول دخول.</p><select id="pinEmployee">'+employeeOptions()+'</select><input id="pinCustom" inputmode="numeric" maxlength="12" placeholder="اختياري: اكتبي رمزًا من 6 أرقام"><button class="staff-primary" onclick="issueStaffPin()">إصدار الرمز المؤقت</button><div id="issuedPin"></div></section><section class="staff-card"><h3>حماية الحساب</h3><ul><li>إيقاف مؤقت بعد خمس محاولات خاطئة.</li><li>الجلسة تنتهي تلقائيًا بعد 12 ساعة.</li><li>كل عملية مرتبطة باسم الموظفة وصلاحيتها.</li><li>البيانات الصحية والاجتماعية محجوبة عن غير المخولين.</li></ul></section></div><section class="staff-card bulk-pin-card"><h2>📋 إصدار رموز لعدة موظفات دفعة واحدة</h2><p class="staff-help">علّمي الموظفات اللي تبين تصدرين لهن رمزًا مؤقتًا جديدًا — هذا يُلغي أي رمز سابق لها، فهو مخصّص للموظفات الجديدات أو اللي فقدن رمزهن. بعد الإصدار اطبعي القائمة أو صدّريها لتسليمها لهن.</p><div class="bulk-pin-actions"><button class="staff-ghost" onclick="bulkPinSelectAll(true)">تحديد الكل</button><button class="staff-ghost" onclick="bulkPinSelectAll(false)">إلغاء التحديد</button></div><div class="bulk-pin-list" id="bulkPinList">'+secureDirectory.employees.map(x=>'<label class="bulk-pin-row"><input type="checkbox" class="bulk-pin-check" value="'+esc(x.short_name)+'"><span>'+esc(x.short_name)+'</span><small>'+esc(x.role||'')+'</small></label>').join('')+'</div><button class="staff-primary" onclick="issueBulkPins()">🔐 إصدار رموز للمحددات</button><div id="bulkPinProgress"></div><div id="bulkPinResultWrap" style="display:none"><div class="bulk-pin-toolbar"><button class="staff-ghost" onclick="printBulkPins()">🖨️ طباعة القائمة</button><button class="staff-ghost" onclick="exportBulkPinsCsv()">⬇️ تصدير CSV</button></div><table class="bulk-pin-table" id="bulkPinTable"></table></div></section><section class="staff-card staff-msg-card"><h2>📨 إرسال رسالة لمعلمات محددات</h2><p class="staff-help">تصل كإشعار مباشر لجهاز المعلمة (يلزم تفعيلها من طرفها من 🔔 إشعارات الحصص). اختاري المعلمات، عدّلي العنوان والنص كما تحبين، ثم أرسلي — لاجتماع، تذكير، مهمة، أو أي تواصل آخر.</p><div class="bulk-pin-actions"><button class="staff-ghost" onclick="staffMsgSelectAll(true)">تحديد الكل</button><button class="staff-ghost" onclick="staffMsgSelectAll(false)">إلغاء التحديد</button></div><div class="bulk-pin-list" id="staffMsgList">'+secureDirectory.employees.map(x=>'<label class="bulk-pin-row"><input type="checkbox" class="staff-msg-check" value="'+esc(x.short_name)+'"><span>'+esc(x.short_name)+'</span><small>'+esc(x.role||'')+'</small></label>').join('')+'</div><div class="form-row"><select id="staffMsgKind" onchange="staffMsgApplyTemplate()"><option value="">— اختاري نوع الرسالة (اختياري) —</option><option value="📣 اجتماع">📣 اجتماع</option><option value="⏰ تذكير">⏰ تذكير</option><option value="📝 مهمة من الإدارة">📝 مهمة من الإدارة</option><option value="📅 فعالية">📅 فعالية</option></select><input id="staffMsgTitle" placeholder="عنوان الرسالة" value="📣 من الإدارة"></div><textarea id="staffMsgText" rows="3" placeholder="نص الرسالة، مثال: يوجد اجتماع في الحصة الثالثة بغرفة المعلمات، الرجاء الحضور"></textarea><button class="staff-primary" id="staffMsgSendBtn" onclick="sendStaffMessage()">📨 إرسال للمحددات</button><div id="staffMsgResult"></div><h3 style="margin-top:16px">آخر الرسائل المرسلة</h3><div class="staff-msg-history" id="staffMsgHistory">جاري التحميل…</div></section><section class="staff-card"><h2>📱 حفظ أرقام واتساب المعلمات</h2><p class="staff-help">الصقي كل معلمة في سطر: الاسم، ثم فاصلة، ثم رقمها (٨ أرقام). تُحفظ في ملفها المهني ويستخدمها زر إبلاغ واتساب تلقائيًا لجميع من يدخلن النظام، بدون إدخال الرقم يدويًا كل مرة.<br>مثال:<br>ثريا الناعبية، 91234567</p><textarea id="phoneImportBox" rows="6" placeholder="ثريا الناعبية، 91234567&#10;فاطمة البطاشية، 92345678"></textarea><button class="staff-primary" onclick="importTeacherPhones()">📱 حفظ الأرقام</button><div id="phoneImportResult"></div></section>';loadStaffMessageLog()}
window.importTeacherPhones=async()=>{
 const lines=(S('phoneImportBox').value||'').split('\n').map(x=>x.trim()).filter(Boolean);
 if(!lines.length)return toast('الصقي الأسماء والأرقام أولًا');
 const phones=lines.map(line=>{const parts=line.split(/[,،\t-]/).map(x=>x.trim()).filter(Boolean);return {name:parts[0]||'',phone:parts.slice(1).join('')}});
 const box=S('phoneImportResult');box.textContent='جاري الحفظ…';
 try{const d=await staffApi('import_teacher_phones',{phones});box.innerHTML='<div class="issued-pin">✅ تم حفظ <b>'+d.ok+'</b> رقم'+(d.failed?.length?'<br><small style="color:#9b1c31">لم يتم التعرف على: '+d.failed.map(esc).join('، ')+'</small>':'')+'</div>';if(d.ok)S('phoneImportBox').value=''}catch(e){box.textContent='';toast(staffError(e))}
};
window.staffMsgSelectAll=v=>document.querySelectorAll('.staff-msg-check').forEach(x=>x.checked=v);
window.staffMsgApplyTemplate=()=>{const k=S('staffMsgKind').value;if(k)S('staffMsgTitle').value=k};
window.sendStaffMessage=async()=>{
 const names=[...document.querySelectorAll('.staff-msg-check:checked')].map(x=>x.value),title=S('staffMsgTitle').value.trim(),message=S('staffMsgText').value.trim(),btn=S('staffMsgSendBtn');
 if(!names.length)return toast('اختاري معلمة واحدة على الأقل');
 if(!title||!message)return toast('اكتبي عنوان الرسالة ونصها');
 if(btn){btn.disabled=true;btn.textContent='جاري الإرسال…'}
 try{
  const d=await staffApi('send_staff_message',{employee_names:names,title,message});
  S('staffMsgResult').innerHTML='<div class="issued-pin">✅ وصلت فورًا لـ '+d.sent+' من '+d.total+' — البقية يحتجن تفعيل إشعارات الجهاز.</div>';
  S('staffMsgText').value='';document.querySelectorAll('.staff-msg-check').forEach(x=>x.checked=false);
  await loadStaffMessageLog()
 }catch(e){toast(staffError(e))}finally{if(btn){btn.disabled=false;btn.textContent='📨 إرسال للمحددات'}}
};
async function loadStaffMessageLog(){
 const box=S('staffMsgHistory');if(!box)return;
 try{
  const d=await staffApi('recent_staff_messages'),items=d.items||[],grouped=new Map();
  items.forEach(x=>{const k=x.title+'|'+x.body+'|'+x.created_at;if(!grouped.has(k))grouped.set(k,{title:x.title,body:x.body,created_at:x.created_at,names:[]});grouped.get(k).names.push(x.employee_name)});
  const rows=[...grouped.values()].slice(0,20);
  box.innerHTML=rows.map(r=>'<div class="staff-msg-history-item"><b>'+esc(r.title)+'</b><small>'+esc(r.body)+'</small><small>إلى: '+esc(r.names.join('، '))+' • '+new Intl.DateTimeFormat('ar-OM',{dateStyle:'short',timeStyle:'short',hour12:true}).format(new Date(r.created_at))+'</small></div>').join('')||'<div class="staff-empty">لا توجد رسائل مرسلة بعد.</div>'
 }catch{box.innerHTML=''}
}
window.issueStaffPin=async()=>{try{const d=await staffApi('issue_pin',{employee_name:S('pinEmployee').value,pin:S('pinCustom').value});S('issuedPin').innerHTML='<div class="issued-pin"><small>الرمز المؤقت لـ '+esc(d.employee_name)+'</small><b>'+esc(d.temporary_pin)+'</b><p>سلّميه لها بصورة خاصة؛ سيطلب النظام تغييره.</p></div>'}catch(e){toast(staffError(e))}};
window.bulkPinSelectAll=v=>{document.querySelectorAll('.bulk-pin-check').forEach(c=>c.checked=v)};
let bulkPinResults=[];
window.issueBulkPins=async()=>{
 const names=[...document.querySelectorAll('.bulk-pin-check:checked')].map(c=>c.value);
 if(!names.length)return toast('اختاري موظفة واحدة على الأقل');
 if(!confirm('سيُصدَر رمز جديد لعدد '+names.length+' موظفة، وسيُلغى أي رمز سابق لهن. متابعة؟'))return;
 bulkPinResults=[];
 const prog=S('bulkPinProgress');
 for(let i=0;i<names.length;i++){
  prog.textContent='جاري الإصدار… ('+(i+1)+'/'+names.length+')';
  try{const d=await staffApi('issue_pin',{employee_name:names[i]});bulkPinResults.push({name:d.employee_name,pin:d.temporary_pin,ok:true})}
  catch(e){bulkPinResults.push({name:names[i],pin:'',ok:false,err:staffError(e)})}
 }
 prog.textContent='';
 renderBulkPinTable();
 toast('✅ تم إصدار '+bulkPinResults.filter(x=>x.ok).length+' رمزًا من أصل '+names.length);
};
function renderBulkPinTable(){
 S('bulkPinResultWrap').style.display=bulkPinResults.length?'block':'none';
 S('bulkPinTable').innerHTML='<thead><tr><th>#</th><th>الاسم</th><th>الرمز المؤقت</th></tr></thead><tbody>'+bulkPinResults.map((r,i)=>'<tr'+(r.ok?'':' class="bulk-pin-err"')+'><td>'+(i+1)+'</td><td>'+esc(r.name)+'</td><td class="bulk-pin-code">'+(r.ok?esc(r.pin):esc(r.err||'تعذر الإصدار'))+'</td></tr>').join('')+'</tbody>';
}
window.printBulkPins=()=>{
 if(!bulkPinResults.length)return toast('لا توجد قائمة لطباعتها');
 const rows=bulkPinResults.map((r,i)=>'<tr><td>'+(i+1)+'</td><td>'+esc(r.name)+'</td><td style="direction:ltr;font-weight:900;letter-spacing:2px">'+(r.ok?esc(r.pin):'—')+'</td></tr>').join('');
 const win=window.open('','_blank');if(!win)return toast('يرجى السماح بالنوافذ المنبثقة للطباعة');
 win.document.write('<html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>الرموز المؤقتة</title><style>body{font-family:Tahoma,Arial,sans-serif;padding:24px;color:#10203c}h2{text-align:center}p{text-align:center;color:#555;font-size:12px}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #999;padding:9px 11px;text-align:right;font-size:14px}th{background:#eee}</style></head><body><h2>مدرسة ملتقى المعارف للتعليم الأساسي (١-٦)</h2><p>الرموز المؤقتة الخاصة بالموظفات — سلّمي كل رمز بصورة خاصة، وسيُطلب من الموظفة تغييره عند أول دخول.</p><table><thead><tr><th>#</th><th>الاسم</th><th>الرمز المؤقت</th></tr></thead><tbody>'+rows+'</tbody></table><script>window.onload=()=>window.print()<'+'/script></body></html>');
 win.document.close();
};
window.exportBulkPinsCsv=()=>{
 if(!bulkPinResults.length)return toast('لا توجد قائمة لتصديرها');
 const rows=[['#','الاسم','الرمز المؤقت']].concat(bulkPinResults.map((r,i)=>[i+1,r.name,r.ok?r.pin:'']));
 const csv='﻿'+rows.map(r=>r.join(',')).join('\n');
 const a=document.createElement('a');
 a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
 a.download='الرموز_المؤقتة.csv';a.click();
};
let schoolCalendarEvents=[];
async function renderSchoolEvents(){
 const d=await staffApi('calendar_events');schoolCalendarEvents=d.items||[];const manage=!!d.can_manage;
 S('staffPane').innerHTML='<div class="today-title"><div><small>مرتبطة بتقويم الفعاليات وإشعارات الخلفية</small><h2>📅 المواعيد المهمة</h2></div></div>'+(manage?'<section class="staff-card"><h3>إضافة أو تعديل موعد</h3><input type="hidden" id="schoolEventId"><div class="staff-form-grid"><label>عنوان الموعد<input id="schoolEventTitle" placeholder="مثال: إدخال التقرير الوصفي"></label><label>التاريخ<input id="schoolEventDate" type="date"></label><label>الوقت (اختياري)<input id="schoolEventTime" type="time"></label><label>التنبيه قبل الموعد<select id="schoolEventReminder"><option value="0">في اليوم نفسه</option><option value="1" selected>قبل يوم</option><option value="2">قبل يومين</option><option value="3">قبل 3 أيام</option><option value="7">قبل أسبوع</option></select></label><label>المستلمات<select id="schoolEventAudience"><option value="all">جميع الموظفات</option><option value="teachers">المعلمات</option><option value="management">الإدارة</option></select></label><label>تفاصيل<textarea id="schoolEventDetails" rows="2"></textarea></label></div><div class="staff-actions"><button class="staff-primary" onclick="saveSchoolEvent()">حفظ وربط بالتقويم</button><button onclick="clearSchoolEventForm()">مسح الحقول</button></div></section>':'')+'<section class="staff-card"><h3>المواعيد المسجلة</h3><div class="staff-table-wrap"><table class="staff-table"><thead><tr><th>الموعد</th><th>التاريخ</th><th>التنبيه</th><th>الفئة</th>'+(manage?'<th>تعديل</th>':'')+'</tr></thead><tbody>'+schoolCalendarEvents.map(x=>'<tr><td><b>'+esc(x.title)+'</b><small>'+esc(x.details||'')+'</small></td><td>'+esc(x.event_date)+(x.event_time?' • '+esc(String(x.event_time).slice(0,5)):'')+'</td><td>قبل '+Number(x.reminder_days||0)+' يوم</td><td>'+({all:'الجميع',teachers:'المعلمات',management:'الإدارة'}[x.audience]||x.audience)+'</td>'+(manage?'<td><button onclick="editSchoolEvent(\''+x.id+'\')">تعديل</button> <button onclick="deleteSchoolEvent(\''+x.id+'\')">حذف</button></td>':'')+'</tr>').join('')+'</tbody></table></div></section>';
}
window.clearSchoolEventForm=()=>{['schoolEventId','schoolEventTitle','schoolEventDate','schoolEventTime','schoolEventDetails'].forEach(id=>{if(S(id))S(id).value=''});if(S('schoolEventReminder'))S('schoolEventReminder').value='1';if(S('schoolEventAudience'))S('schoolEventAudience').value='all'};
window.editSchoolEvent=id=>{const x=schoolCalendarEvents.find(v=>v.id===id);if(!x)return;S('schoolEventId').value=x.id;S('schoolEventTitle').value=x.title||'';S('schoolEventDate').value=x.event_date||'';S('schoolEventTime').value=String(x.event_time||'').slice(0,5);S('schoolEventReminder').value=String(x.reminder_days??1);S('schoolEventAudience').value=x.audience||'all';S('schoolEventDetails').value=x.details||'';S('schoolEventTitle').focus()};
window.saveSchoolEvent=async()=>{try{await staffApi('save_calendar_event',{id:S('schoolEventId').value,title:S('schoolEventTitle').value,event_date:S('schoolEventDate').value,event_time:S('schoolEventTime').value,reminder_days:Number(S('schoolEventReminder').value),audience:S('schoolEventAudience').value,details:S('schoolEventDetails').value,published:true});toast('✅ تم حفظ الموعد وربطه بالتقويم والتنبيه');await renderSchoolEvents()}catch(e){toast(staffError(e))}};
window.deleteSchoolEvent=async id=>{if(!confirm('حذف هذا الموعد من التقويم؟'))return;try{await staffApi('delete_calendar_event',{id});toast('تم حذف الموعد');await renderSchoolEvents()}catch(e){toast(staffError(e))}};

